import * as G from './horizons.js';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.floor(n||0).toLocaleString('es-CO'),goods=o=>Object.entries(o||{}).filter(([,n])=>n>0).map(([k,n])=>fmt(n)+' '+G.STOCK_NAMES[k]).join(' · ')||'Sin existencias';
const button=(action,label,id='',type='')=>`<button data-action="${action}" data-id="${id}" data-type="${type}">${label}</button>`;
export let view='production';
export const form={a:'',b:'',vehicle:'',resource:'wood',amount:10};
export function setView(value){if(['production','engineering','logistics'].includes(value))view=value;}
export function updateForm(key,value){if(key in form)form[key]=key==='amount'?Number(value):value;}
export function buildingDetails(s,b){const m=G.currentMap(s),spec=G.STRUCTURES[b.type],r=G.RECIPES[b.type],d=G.DEFENSES[b.type],staff=m.units.filter(u=>u.assignment?.building===b.id&&u.hp>0).length;
 return `<div class="facility-details"><p>${esc(G.SERVICES[b.type]||spec.description)}</p>${r?`<p class="recipe-line">${r.source?'Yacimiento local de '+G.STOCK_NAMES[r.source]:goods(r.input)} <b>→</b> ${goods(r.output)}<small>${r.seconds} s de trabajo por lote y operario · nivel ×${G.buildingStats(b,spec).output.toFixed(2)}</small></p>`:''}${d?`<p>${d.shield?'Protección local: −35% del daño recibido':`Alcance ${d.range} · daño ${d.damage} · ${d.target==='air'?'Objetivos aéreos':d.target==='naval'?'Objetivos navales':'Objetivos terrestres'}`}<br>${d.cost?goods({[d.cost]:d.use})+' por disparo':'Requiere energía'}</p>`:''}<div class="side-line"><span>Estado</span><strong>${esc(b.status||'Preparada')}</strong></div><div class="side-line"><span>Personal</span><strong>${staff} / 4</strong></div><p class="local-stock">Almacén de esta instalación: ${goods(G.buildingStore(m,b))}</p>${b.progress>=1&&(spec.expansion||d)?button('staff-building','Asignar un operario libre',b.id,'industry'):''}${button('collect-store','Recoger carga con un colono',b.id)}${button('focus-facility','Localizar',b.id)}</div>`;
}
function production(s){const m=G.currentMap(s),list=m.buildings.filter(b=>b.hp>0&&(G.STRUCTURES[b.type].expansion||G.DEFENSES[b.type]));return `<p>Los operarios llevan insumos desde el campamento o almacén hasta su instalación. La producción permanece allí: usa una ruta para recogerla. Los yacimientos se agotan; un edificio sin personal no produce.</p><div class="inventory">${['boards','flour','parts','medicine','ammo','leather'].map(k=>`<div><small>${G.STOCK_NAMES[k]}</small><strong>${fmt(m.stock[k])}</strong><small>En almacenes: ${fmt(list.reduce((n,b)=>n+(b.store?.[k]||0),0))}</small></div>`).join('')}</div><div class="facility-list">${list.map(b=>`<details class="facility"><summary><span>${G.STRUCTURES[b.type].name}<small>${esc(b.status||'Preparada')} · nivel ${b.level}</small></span><span>${goods(b.store)}</span></summary>${buildingDetails(s,b)}${button('inspect-upgrade','Información y mejoras',b.id)}</details>`).join('')||'<div class="empty">Construye un aserradero, cantera o puesto de caza desde Construir → Recursos.</div>'}</div>`;}
function engineering(s){const m=G.currentMap(s),i=m.industry;return `<p>Explora y despeja el corredor. Traza desde Caminos, envía un trabajador a estudiarlo, revisa el presupuesto y confirma la construcción. Cada casilla representa 4 m y cada nivel de terreno, 1 m en los cálculos del juego.</p><div class="toolbar"><select id="road-grade" aria-label="Acabado">${Object.entries(G.ROAD_GRADES).map(([k,v])=>`<option value="${k}" ${s.era<v.era?'disabled':''}>${v.name} · era ${v.era+1}</option>`).join('')}</select>${button('road-tool','Trazar recta','','straight')}${button('road-tool','Trazar curva','','curve')}</div><div class="toolbar">${[['pipe','Tubería'],['raise','Elevar terreno'],['wall','Muralla']].map(([id,name])=>button('tool',name,'',id)).join('')}</div><h3>Estudios y obras</h3>${i.surveys.filter(j=>!j.done).map(j=>`<div class="work-row"><span>Estudio ${j.kind==='defense'?'de defensa':'del corredor'}<small>${j.index} / ${j.cells.length} casillas · ${esc(j.id)}</small></span>${button('resume-work','Asignar trabajador',j.id)}</div>`).join('')}${i.projects.filter(j=>!j.done&&!j.cancelled).map(j=>`<div class="work-row"><span>${G.ROAD_GRADES[j.grade].name}<small>${j.index} / ${j.steps.length} tramos · ${goods(j.cost)}</small></span>${button('resume-work','Continuar',j.id)}${button('cancel-project','Cancelar',j.id)}</div>`).join('')||'<p>Sin obras pendientes.</p>'}<p>${i.surveys.filter(j=>j.done).length} estudios completados · ${i.projects.filter(j=>j.done).length} corredores construidos</p><h3>Puentes en servicio</h3>${i.bridges.map(b=>`<details class="facility"><summary><span>${b.closed?'CERRADO':'En servicio'} · ${Math.round(b.condition*100)}%<small>${b.cells.length*4} m · ${b.design.material}</small></span><span>${(b.design.vehicle+b.report.capacityPayloadTonnes).toFixed(1)} t totales</span></summary><p>Vida estimada ${b.report.lifeYears.toFixed(1)} años de juego · ${b.crossings} pasos. Flecha ${b.report.deflectionMm.toFixed(1)} mm · tensión ${b.report.stressMPa.toFixed(1)} MPa. Las catástrofes y el uso reducen su condición; una reparación conserva su capacidad nominal.</p>${button('bridge-inspect','Inspeccionar',b.id)}${button('bridge-repair','Reparar',b.id)}${button('focus-bridge','Localizar',b.id)}</details>`).join('')||'<p>Los puentes aparecerán al completar las obras.</p>'}<p class="callout">Estas fórmulas sirven a la simulación. No constituyen un cálculo estructural para construir en la vida real.</p>`;}
function logistics(s){const m=G.currentMap(s),buildings=m.buildings.filter(b=>b.hp>0&&b.progress>=1),vehicles=m.units.filter(u=>u.hp>0&&!u.embarked&&!u.inTransit&&G.TRANSPORT_TYPES[u.type]),i=m.industry;
 if(!buildings.some(b=>b.id===form.a))form.a=buildings[0]?.id||'';if(!buildings.some(b=>b.id===form.b)||form.b===form.a)form.b=buildings.find(b=>b.id!==form.a)?.id||'';if(!vehicles.some(u=>u.id===form.vehicle))form.vehicle=vehicles[0]?.id||'';
 const opts=chosen=>buildings.map(b=>`<option value="${b.id}" ${b.id===chosen?'selected':''}>${G.STRUCTURES[b.type].name} · ${b.id}</option>`).join(''),q=G.lineQuote(s,form.a,form.b,form.vehicle,form.resource,form.amount);
 return `<p>Crea un vehículo en su instalación y conecta dos almacenes. Los caballos siguen terreno transitable; carretas, camiones y trenes exigen su red continua. Barcos y aeronaves necesitan terminales y un corredor estudiado. La carga viaja con el vehículo y se pierde si es destruido.</p><div class="route-form"><label>Origen<select data-line-field="a">${opts(form.a)}</select></label><label>Destino<select data-line-field="b">${opts(form.b)}</select></label><label>Vehículo propio<select data-line-field="vehicle">${vehicles.map(u=>`<option value="${u.id}" ${u.id===form.vehicle?'selected':''}>${G.TROOPS[u.type].name} · ${u.id} · ${G.TRANSPORT_TYPES[u.type].capacity} carga</option>`).join('')}</select></label><label>Recurso<select data-line-field="resource">${Object.entries(G.STOCK_NAMES).map(([k,v])=>`<option value="${k}" ${k===form.resource?'selected':''}>${v}</option>`).join('')}</select></label><label>Cantidad<input data-line-field="amount" type="number" min="1" max="450" step="1" value="${form.amount}"></label></div><p id="line-quote">${q.ok?`${q.distance} m · masa con carga ${q.totalMass.toFixed(2)} t · ${q.studied?'Estudio vigente':'Estudio pendiente'}`:esc(q.message)}</p><div class="toolbar"><button data-action="survey-line" ${!q.ok||q.studied?'disabled':''}>Estudiar itinerario</button><button class="primary" data-action="create-line" ${!q.ok||!q.studied?'disabled':''}>Abrir ruta</button></div><h3>Convoyes locales</h3>${i.lines.filter(r=>!r.cancelled).map(r=>`<details class="facility"><summary><span>${G.TROOPS[r.vehicleType].name} · ${G.STOCK_NAMES[r.resource]}<small>${esc(r.status)} · ${r.amount} por viaje</small></span><span>${fmt(r.delivered)} entregados</span></summary><p>Carga a bordo ${fmt(r.cargo)} · Perdido ${fmt(r.lost)} · ${r.points.length*4} m. El vehículo debe recoger y entregar físicamente; no aparecen vehículos de reemplazo.</p>${button('line-action',r.paused?'Reanudar':'Pausar',r.id,r.paused?'resume':'pause')}${button('line-action','Retirar ruta',r.id,'cancel')}${button('focus-worker','Localizar vehículo',r.vehicle)}</details>`).join('')||'<div class="empty">Crea un caballo de carga en el establo para empezar.</div>'}`;
}
export function settlementPanel(s){return `<div class="panel-head"><div><span class="eyebrow">EL IMPERIO FUNCIONA POR SUS CONEXIONES</span><h2>Producción y suministros</h2></div>${button('close-panel','×')}</div><div class="settlement-tabs" role="tablist">${[['production','Instalaciones'],['engineering','Ingeniería'],['logistics','Convoyes']].map(([k,n])=>`<button role="tab" aria-selected="${view===k}" class="${view===k?'active':''}" data-action="settlement-tab" data-type="${k}">${n}</button>`).join('')}</div>${{production,engineering,logistics}[view](s)}`;}
export function personDialog(s,id){const m=G.currentMap(s),p=m.industry.people.find(p=>p.id===id);if(!p)return'';const r=G.NPC_ROLES[p.role],available=s.time>=p.available;return `<div class="panel-head"><h2>${r.name}</h2>${button('close-modal','×')}</div><p>Necesito ${goods(r.cost)}. Tu ayuda vale ${r.reward} áureos y +${r.morale} de moralidad.${p.role==='refugee'?' También necesitamos una plaza: un colono se unirá al pueblo.':''}</p><p>${available?'Encargo disponible':'Volverá a necesitar ayuda en '+Math.ceil((p.available-s.time)/60)+' min'} · ${p.completed} encargos resueltos</p><div class="actions"><button class="primary" data-action="person-choice" data-id="${id}" data-type="help" ${available?'':'disabled'}>Entregar ayuda</button><button data-action="person-choice" data-id="${id}" data-type="deny" ${available?'':'disabled'}>Rechazar · −2 moralidad</button></div>`;}
export function peopleCards(s){const m=G.currentMap(s);return `<h3>Visitantes del pueblo</h3><p>Los visitantes aparecen junto a instalaciones terminadas. Tócalos en el territorio o atiende sus encargos aquí. Cada decisión queda registrada.</p><div class="visitor-list">${m.industry.people.map(p=>`<div class="work-row"><span>${G.NPC_ROLES[p.role].name}<small>${s.time>=p.available?'Necesita ayuda':'Encargo atendido'}</small></span>${button('person-dialog','Hablar',p.id)}${button('focus-person','Localizar',p.id)}</div>`).join('')||'<div class="empty">Funda el campamento para recibir al explorador; otros oficios aparecen con sus instalaciones.</div>'}</div>`;}
export function roadBanner(s,tool,points,grade,design){const complete=points.length===(tool==='road-curve'?3:2),q=complete?G.projectQuote(s,points,grade,tool==='road-curve',design):null;return `<div class="placement-title"><div><strong>${G.ROAD_GRADES[grade].name}</strong><small id="road-price">${q?q.ok?goods(q.cost)+(q.studied?' · Estudio vigente':' · Necesita estudio'):esc(q.error):tool==='road-curve'?'Marca inicio, control y final.':'Marca inicio y final o arrastra.'}</small></div></div>${complete?`<details class="bridge-design"><summary>Terreno y diseño del puente</summary><p>${q?.ok?`Corte ${q.cut} m³ · relleno ${q.fill} m³ · reutilización ${q.reused} piedra · pendiente ${q.slope.toFixed(1)}%`:''}</p><div class="route-form"><label>Material<select data-bridge-field="material">${[['timber','Madera'],['steel','Acero'],['reinforced','Hormigón']].map(([k,n])=>`<option value="${k}" ${design.material===k?'selected':''}>${n}</option>`).join('')}</select></label>${[['vehicle','Vehículo (t)',1],['payload','Carga (t)',3],['years','Vida objetivo (años)',15],['beamHeight','Canto de viga (m)',.65],['supports','Apoyos intermedios',0]].map(([k,n,d])=>`<label>${n}<input data-bridge-field="${k}" type="number" min="${k==='beamHeight'?.15:0}" step="${k==='beamHeight'?.05:1}" value="${design[k]??q?.bridges?.[0]?.design[k]??d}"></label>`).join('')}</div>${q?.bridges?.map(b=>`<p>${b.design.length} m · límite ${(b.design.vehicle+b.report.capacityPayloadTonnes).toFixed(1)} t · vida ${b.report.lifeYears.toFixed(1)} años · ${b.report.ok?'Apto':esc(b.report.reasons.join(' · '))}</p>`).join('')||''}</details>`:''}<div class="placement-actions"><button data-action="cancel-tool">Cerrar</button><button data-action="restart-road">Otro trazado</button><button data-action="study-road" ${!complete||!q?.ok||q.studied?'disabled':''}>Estudiar terreno</button><button class="primary" data-action="confirm-road" ${!complete||!q?.ok||!q.studied?'disabled':''}>Construir</button></div>`;}
